 if((all=s.match(/^([٠-٩0-9]+) · (كلمات الوحدة|جمل الوحدة|الأصوات|أسئلة الوحدة|التحيات والتعارف|تعليمات الفصل|حوار الوحدة|مين ده؟|عدّ الحيوانات|عدّ أجزاء جسمك|فين؟ وكام رجل؟|الأرقام من ١ لـ ٥)$/)))return digits(all[1])+' · '+({'كلمات الوحدة':'Unit words','جمل الوحدة':'Unit sentences','الأصوات':'Sounds','أسئلة الوحدة':'Unit questions','التحيات والتعارف':'Greetings and introductions','تعليمات الفصل':'Classroom instructions','حوار الوحدة':'Unit dialogue','مين ده؟':'Who is this?','عدّ الحيوانات':'Count the animals','عدّ أجزاء جسمك':'Count body parts','فين؟ وكام رجل؟':'Where? How many legs?','الأرقام من ١ لـ ٥':'Numbers 1 to 5'}[all[2]]);
 if((all=s.match(/^من كتاب الأداءات والتقييمات \(ص (.+)\) [—–-] أسئلة الكتاب نفسه بتصحيح فوري بعد كل سؤال\.$/)))return 'From the assessment book (pp. '+digits(all[1])+'), with instant feedback after each question.';

 if(dict.has(s))return dict.get(s);
 let routeMatch;
 if((routeMatch=s.match(/^اخترنا ([0-9٠-٩]+) من ([0-9٠-٩]+)$/)))return "Selected "+digits(routeMatch[1])+" of "+digits(routeMatch[2]);
 if((routeMatch=s.match(/^اللعبة ([0-9٠-٩]+) من ([0-9٠-٩]+)$/)))return "Game "+digits(routeMatch[1])+" of "+digits(routeMatch[2]);
 if((routeMatch=s.match(/^جولة ([0-9٠-٩]+) من ([0-9٠-٩]+)$/)))return "Round "+digits(routeMatch[1])+" of "+digits(routeMatch[2]);
 if((routeMatch=s.match(/^الوحدة ([0-9٠-٩]+) · محاولة ([0-9٠-٩]+) من ([0-9٠-٩]+)$/)))return 'Unit '+digits(routeMatch[1])+' · Attempt '+digits(routeMatch[2])+' of '+digits(routeMatch[3]);
 if((routeMatch=s.match(/^Lesson ([0-9]+): (.+) · ([0-9]+) سؤالًا\.$/)))return 'Lesson '+routeMatch[1]+': '+routeMatch[2]+' · '+routeMatch[3]+' questions.';
 if((routeMatch=s.match(/^بطاقات تفاعلية · (.+)$/)))return 'Interactive cards · '+english(routeMatch[1]);
 if((routeMatch=s.match(/^بطاقات مراجعة الوحدات ([0-9٠-٩-]+) التفاعلية$/)))return 'Interactive revision cards · Units '+digits(routeMatch[1]);
 if((routeMatch=s.match(/^بطاقات الوحدة ([0-9٠-٩]+): (.+) التفاعلية$/)))return 'Unit '+digits(routeMatch[1])+': '+routeMatch[2]+' interactive cards';

 const ordinalMedia={'الأولى':'1','الثانية':'2','الثالثة':'3','الرابعة':'4','الخامسة':'5','السادسة':'6'};
