 if((routeMatch=s.match(/^شرح الوحدة (الأولى|الثانية|الثالثة|الرابعة|الخامسة|السادسة)( كاملة)? · (المنهج السعودي|٤ دروس)$/)))return 'Unit '+ordinalMedia[routeMatch[1]]+(routeMatch[2]?' full':'')+' lesson · '+(routeMatch[3]==='٤ دروس'?'4 lessons':'Saudi curriculum');
 if((routeMatch=s.match(/^Primary ([0-9]+) سعودي$/)))return 'Saudi Primary '+routeMatch[1];
 if((routeMatch=s.match(/^([0-9]+) فيديو متاح$/)))return routeMatch[1]+' videos available';
 if((routeMatch=s.match(/^([0-9:]+) · افتح فيديو الوحدة ←$/)))return routeMatch[1]+' · Open unit video ←';

 if((routeMatch=s.match(/^درجة (.+) هي ([0-9]+) من ([0-9]+) ✅$/)))return routeMatch[1]+"'s score is "+routeMatch[2]+' out of '+routeMatch[3]+' ✅';
 if((routeMatch=s.match(/^آخر تحديث: ([0-9-]+)$/)))return 'Last updated: '+routeMatch[1];
