 if((routeMatch=s.match(/^([0-9]+) وحدات من الجزء الأول، ([0-9]+) سؤالًا أصليًا بالتصحيح الفوري\.$/)))return routeMatch[1]+' units from Part 1, with '+routeMatch[2]+' original questions and instant marking.';
 if((routeMatch=s.match(/^المرجع: كتاب (.+)، الجزء الأول، وزارة التعليم، (2026 \/ 1448)(، ISBN [0-9]+)?\. الشرح والأسئلة على الموقع من إعداد ENGLISH SAVANT، وليست نقلًا لأسئلة الكتاب\.$/)))return 'Reference: '+routeMatch[1]+', Part 1, Ministry of Education, '+routeMatch[2]+(routeMatch[3]?routeMatch[3].replace('،',','):'')+'. The explanations and questions on the site are ENGLISH SAVANT work, not copies of the book\'s questions.';
