 if((routeMatch=s.match(/^مراجعة ([0-9]+–[0-9]+) · صفحات ([0-9]+–[0-9]+)$/)))return 'Units '+routeMatch[1]+' revision · pages '+routeMatch[2];

 if((routeMatch=s.match(/^([0-9]+) وحدات · ([0-9]+) سؤال تفاعلي$/)))return routeMatch[1]+' units · '+routeMatch[2]+' interactive questions';
