 if((routeMatch=s.match(/^([0-9]+) أنشطة متاحة\. صور الكلمات بتسمّع المعنى بالعربي وبعده الكلمة بالإنجليزي، وفيه تدريب اسمع واختار الصورة\. باقي الصوت والتدريبات لسه بتتجهز\.$/)))return routeMatch[1]+' activities available. Word pictures play the Arabic meaning followed by the English word, with listen-and-choose-picture practice. Remaining audio and assessments are still being prepared.';

 if(s.startsWith('تدريب: ')){let t=s.slice('تدريب: '.length).replace('، تقدير تجريبي مش شهادة.','');return 'Practice: '+t.split(' · ').map(english).join(' · ')+', provisional estimate, not a certificate.';}
 if(s.endsWith(':')&&dict.has(s.slice(0,-1)))return dict.get(s.slice(0,-1))+':';
 let exam=s.match(/^تدريب تفاعلي من General Practice on Unit في المصدر المراجع\. ([0-9]+) سؤالًا من غير استماع أو كتابة براجراف\. كل سؤال بدرجة واحدة، ومجموعة الفراغات بدرجة واحدة\. بنحسب أول إجابة لكل سؤال\.$/);if(exam)return 'Interactive practice from General Practice on Unit in the reviewed source. '+exam[1]+' questions, without listening or paragraph writing. Each question is worth one mark, and a group of gaps is worth one mark. Only the first answer to each question is scored.';
