 let activity=s.match(/^نشاط ([0-9٠-٩]+) · (.+)$/);if(activity)return 'Activity '+digits(activity[1])+' · '+english(activity[2]);
 let lesson=s.match(/^الدرس ([0-9٠-٩]+): (.+)$/);if(lesson)return 'Lesson '+digits(lesson[1])+': '+lesson[2];
