 b=s.match(/^السؤال ([0-9٠-٩]+) من ([0-9٠-٩]+)(?: · ([0-9٠-٩]+) من ([0-9٠-٩]+) في النوع ده)?$/);if(b)return 'Question '+digits(b[1])+' of '+digits(b[2])+(b[3]?' · '+digits(b[3])+' of '+digits(b[4])+' in this type':'');
