 let source=s.match(/^أنشطة أداء الصف والواجب والتقييمات الأسبوعية من كتاب الأداءات والتقييمات \(ص ([0-9-]+)\) — بتصحيح فوري\.$/);if(source)return 'Classwork, homework and weekly assessments from the performance and assessment book (pp. '+source[1]+'), with instant feedback.';
